// Reads a JSON Schema on stdin and prints TypeScript (used by scripts/gen_contracts.py).
import { compile } from "json-schema-to-typescript";

let input = "";
for await (const chunk of process.stdin) input += chunk;
const ts = await compile(JSON.parse(input), "Contracts", {
  bannerComment:
    "/* Generated by scripts/gen_contracts.py from the Pydantic schemas. Do not edit. */",
  unreachableDefinitions: true,
  additionalProperties: false,
  strictIndexSignatures: true,
  format: true,
});
process.stdout.write(ts);
